import{At as e,Mt as t,Qt as n,lt as r}from"./chunks/framework.DwOUwJQP.js";var i=JSON.parse(`{"title":"Resource与Autowired注解的区别","description":"","frontmatter":{"title":"Resource与Autowired注解的区别","date":"2020-04-10T17:26:30.000Z","tags":["Spring","java"]},"headers":[],"relativePath":"blogs/java/framework/Resource与Autowired注解的区别.md","filePath":"blogs/java/framework/Resource与Autowired注解的区别.md","lastUpdated":1788090369000}`),a={name:`blogs/java/framework/Resource与Autowired注解的区别.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h5 id="autowired" tabindex="-1">@Autowired <a class="header-anchor" href="#autowired" aria-label="Permalink to “@Autowired”">​</a></h5><blockquote><p>由Spring提供，<strong>默认只按照类型注入</strong>，默认情况下必须要求依赖对象存在，如果要<strong>允许null值</strong>，则可以设置其<strong>require属性</strong>为<strong>false</strong>。</p><p>如果想使用<strong>名称装配</strong>可以结合<strong>@Qualifier注解</strong>进行使用</p></blockquote><h5 id="resource" tabindex="-1">@Resource <a class="header-anchor" href="#resource" aria-label="Permalink to “@Resource”">​</a></h5><blockquote><p>由J2EE提供，<strong>默认按照名称注入</strong>，名称可以通过 <strong>name属性</strong>指定</p><p>如果没有指定name 属性，当注解写到<strong>字段</strong>上，<strong>默认取字段名</strong>进行名称查找；如果注解写到<strong>setter</strong>方法上默认取属性名进行注入。</p><p>当<strong>找不到与名称匹配的bean时</strong>才<strong>按照类型进行注入</strong>。</p><p>需要注意的是，如果name属性一旦指定，就只会按照名称进行装配。若指定<strong>type属性</strong>，则找类型匹配的bean进行注入，找不到抛出异常</p></blockquote>`,4)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};